function escaparRegex(texto) {
  return texto.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function Resaltar({ texto, busqueda }) {
  if (/* búsqueda vacía o en blanco */) return <>{texto}</>;
  const partes = texto.split(new RegExp(`(${escaparRegex(busqueda)})`, "gi"));
  return (
    <>
      {partes.map((parte, i) =>
        /* ¿coincide? */ ? <mark key={i}>{parte}</mark> : parte
      )}
    </>
  );
}
